def utc_now(): return datetime.now(timezone.utc).isoformat()

def jdump(x): return json.dumps(x, ensure_ascii=False, default=str, sort_keys=True)

def cfg_hash(x): return hashlib.sha256(jdump(x).encode()).hexdigest()

def append_jsonl(path: Path, obj: Mapping[str,Any]):
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a",encoding="utf-8") as f:
        f.write(json.dumps(dict(obj),ensure_ascii=False,default=str)+"\n")

def load_latest(path: Path, h: str, key="source_row_index"):
    out={}
    if not path.exists(): return out
    with path.open(encoding="utf-8") as f:
        for line in f:
            try:
                o=json.loads(line)
                if o.get("config_hash")==h and key in o: out[int(o[key])]=o
            except Exception: pass
    return out

def load_module(path: str, name: str):
    p=Path(path)
    if not p.exists(): raise FileNotFoundError(p)
    spec=importlib.util.spec_from_file_location(name,p)
    if spec is None or spec.loader is None: raise RuntimeError(f"Cannot load {p}")
    mod=importlib.util.module_from_spec(spec)
    sys.modules[name]=mod
    spec.loader.exec_module(mod)
    return mod

def load_embedded_module(blob: str, name: str, virtual_filename: str):
    source=gzip.decompress(base64.b64decode(blob.encode("ascii"))).decode("utf-8")
    mod=types.ModuleType(name)
    mod.__file__=virtual_filename
    mod.__package__=""
    sys.modules[name]=mod
    exec(compile(source,virtual_filename,"exec"),mod.__dict__)
    return mod

def target_binary(v):
    try:
        iv=int(float(v))
        return 1 if iv==1 else (0 if iv==2 else None)
    except Exception: return None

def choose_device(name):
    if name=="cpu": return torch.device("cpu")
    if name=="cuda":
        if not torch.cuda.is_available(): raise RuntimeError("CUDA requested but unavailable")
        return torch.device("cuda")
    return torch.device("cuda" if torch.cuda.is_available() else "cpu")

def safe_logit(p):
    p=np.clip(np.asarray(p,dtype=float),1e-5,1-1e-5)
    return np.log(p/(1-p))

def sigmoid(x):
    x=np.clip(np.asarray(x,dtype=float),-40,40)
    return 1/(1+np.exp(-x))

def import_project_modules(args):
    v4=(load_module(args.v4_script,"rg_v4_source") if args.v4_script
        else load_embedded_module(EMBEDDED_V4_GZ_B64,"rg_v4_source","<embedded_v4_flare_vax.py>"))
    v5=(load_module(args.v5_script,"rg_v5_source") if args.v5_script
        else load_embedded_module(EMBEDDED_V5_GZ_B64,"rg_v5_source","<embedded_v5_flare_vax.py>"))
    return v4,v5

def prepare_raw(input_csv, v4, v5, variants):
    needed=set()
    if "v4" in variants: needed.update(v4.REQUIRED_COLUMNS)
    if "v5" in variants: needed.update(v5.REQUIRED_COLUMNS)
    header=set(pd.read_csv(input_csv,nrows=0).columns)
    missing=sorted(needed-header)
    if missing: raise KeyError(f"adult24.csv missing columns: {missing}")
    raw=pd.read_csv(input_csv,usecols=sorted(needed),low_memory=False)
    raw.index=np.arange(len(raw),dtype=int)
    return raw

def build_variant_scores(raw_all, variant, v4, v5):
    if variant=="v4":
        raw=raw_all[list(v4.REQUIRED_COLUMNS)].copy()
        scores=v4.build_scores(raw)
        second="vaccine_acceptance_benefit_proxy"
    else:
        raw=raw_all[list(v5.REQUIRED_COLUMNS)].copy()
        scores=v5.apply_construct_config(v5.build_scores(raw),v5.load_construct_config(""))
        second="preventive_engagement_proxy"
    # Match the original V4/V5 pipelines: selection is target-valid only.
    # Rare construct-level missingness is retained; original pattern logic maps comparisons
    # with NaN conservatively and the reward layer imputes missing construct coordinates at 0.5.
    valid=scores["vaccinated"].isin([0,1])
    raw=raw.loc[valid].copy(); scores=scores.loc[valid].copy()
    scores["source_row_index"]=scores.index.astype(int)
    return raw,scores,second

def load_reference_split(path, raw_all):
    ref=pd.read_csv(path)
    pairs=[("source_index","phase"),("source_row_index","split"),
           ("source_index","split"),("source_row_index","phase")]
    pair=next((x for x in pairs if set(x).issubset(ref.columns)),None)
    if pair is None:
        raise ValueError(f"Unsupported reference split format: {path}")
    a,b=pair
    out=ref[[a,b]].copy(); out.columns=["source_row_index","split"]
    out["source_row_index"]=pd.to_numeric(out["source_row_index"],errors="raise").astype(int)
    out["split"]=out["split"].astype(str).str.lower()
    out=out[out["split"].isin(["memory","calibration","test"])].drop_duplicates("source_row_index")
    out=out[out["source_row_index"].isin(raw_all.index)].copy()
    out["actual"]=[target_binary(raw_all.loc[i,TARGET]) for i in out["source_row_index"]]
    return out[out["actual"].isin([0,1])].reset_index(drop=True)

def fallback_split(scores, seed):
    idx=np.asarray(scores.index,dtype=int)
    y=scores["vaccinated"].astype(int)
    n=len(idx); nm=int(round(.4*n)); nc=int(round(.2*n))
    mem,rest=train_test_split(idx,train_size=nm,random_state=seed,stratify=y.loc[idx])
    cal,test=train_test_split(rest,train_size=nc,random_state=seed+1,stratify=y.loc[rest])
    rows=[]
    for split,arr in [("memory",mem),("calibration",cal),("test",test)]:
        rows.extend({"source_row_index":int(i),"split":split,"actual":int(y.loc[i])} for i in arr)
    return pd.DataFrame(rows)

def downsample_eval(assignments, sample_size, seed):
    if sample_size<=0: return assignments.copy()
    target=assignments[assignments.split.isin(["calibration","test"])].copy()
    if sample_size>=len(target): return assignments.copy()
    frac=sample_size/len(target); pieces=[]; alloc=[]
    groups=list(target.groupby(["split","actual"],sort=True))
    for _,g in groups: alloc.append(max(1,int(round(len(g)*frac))))
    while sum(alloc)>sample_size:
        changed=False
        for i in range(len(alloc)-1,-1,-1):
            if alloc[i]>1:
                alloc[i]-=1; changed=True
                if sum(alloc)==sample_size: break
        if not changed: break
    while sum(alloc)<sample_size:
        changed=False
        for i,(_,g) in enumerate(groups):
            if alloc[i]<len(g):
                alloc[i]+=1; changed=True
                if sum(alloc)==sample_size: break
        if not changed: break
    for j,(_,g) in enumerate(groups):
        pieces.append(g.sample(n=alloc[j],random_state=seed+j))
    return pd.concat([assignments[assignments.split=="memory"],pd.concat(pieces)],ignore_index=True)

def fit_thresholds(memory, mode, fixed):
    if mode=="fixed": return {"motivation":fixed,"capability":fixed,"activation":fixed}
    return {"motivation":float(memory.motivation_score.median()),
            "capability":float(memory.capability_score.median()),
            "activation":float(memory.activation_score.median())}

def assign_patterns(scores, thresholds, variant, v4, v5):
    if variant=="v4":
        return v4.assign_final_patterns(scores,thresholds)
    return v5.assign_patterns(scores,thresholds)

def fit_base_rates(memory, prior_strength):
    overall=float(memory.vaccinated.mean()); out={}
    for p in PATTERN_ORDER:
        g=memory[memory.hbm8_pattern==p]; n=len(g); yes=float(g.vaccinated.sum())
        raw=yes/n if n else overall
        sm=(yes+prior_strength*overall)/(n+prior_strength) if n+prior_strength else overall
        out[p]={"n":int(n),"yes":yes,"raw_rate":raw,"smoothed_rate":sm}
    out["__overall__"]={"n":len(memory),"yes":float(memory.vaccinated.sum()),
                        "raw_rate":overall,"smoothed_rate":overall}
    return out

def construct_matrix(scores, variant):
    second=(scores["vaccine_acceptance_benefit_proxy"] if variant=="v4"
            else scores["preventive_engagement_proxy"])
    x=np.column_stack([
        scores["observed_threat_proxy"].to_numpy(float)/5,
        second.to_numpy(float)/5,
        (5-scores["structural_barrier_proxy"].to_numpy(float))/5,
        scores["healthcare_cue_proxy"].to_numpy(float)/5,
        scores["navigation_self_efficacy_proxy"].to_numpy(float)/5,
    ])
    return np.clip(np.where(np.isfinite(x),x,.5),0,1)

class RewardModel(nn.Module):
    def __init__(self,n_patterns=8):
        super().__init__()
        self.global_raw=nn.Parameter(torch.zeros(5))
        self.pattern_raw=nn.Parameter(torch.zeros(n_patterns,5))
    def global_weights(self): return F.softplus(self.global_raw)
    def multipliers(self): return torch.exp(.45*torch.tanh(self.pattern_raw))
    def effective(self,pidx): return self.global_weights()[None,:]*self.multipliers()[pidx]

@dataclass
class RewardArtifacts:
    global_weights: np.ndarray
    pattern_multipliers: np.ndarray
    pattern_means: np.ndarray
    pattern_names: List[str]
    pmap: Dict[str,int]
    base_rates: Dict[str,Dict[str,float]]

def pattern_arrays(scores, base_rates):
    names=list(PATTERN_ORDER); pmap={p:i for i,p in enumerate(names)}
    pidx=np.array([pmap[str(p)] for p in scores.hbm8_pattern],dtype=int)
    anchor=np.array([base_rates.get(str(p),base_rates["__overall__"])["smoothed_rate"]
                     for p in scores.hbm8_pattern],dtype=float)
    return names,pmap,pidx,anchor

def pattern_means(x,patterns,names):
    out=np.full((len(names),x.shape[1]),.5,dtype=np.float32); pats=np.asarray(patterns,dtype=object)
    for j,p in enumerate(names):
        m=pats==p
        if m.any(): out[j]=np.mean(x[m],axis=0)
    return out

def fit_reward_model(scores,base_rates,variant,args,device):
    x=construct_matrix(scores,variant); y=scores.vaccinated.to_numpy(np.float32)
    names,pmap,pidx,anchor=pattern_arrays(scores,base_rates)
    means=pattern_means(x,scores.hbm8_pattern.astype(str).tolist(),names)
    centered=x-means[pidx]
    sw=scores.survey_weight.to_numpy(float)
    good=np.isfinite(sw)&(sw>0)
    if args.reward_survey_weighted and good.any():
        sw=np.where(good,sw,np.nanmedian(sw[good])); sw=sw/np.mean(sw)
    else: sw=np.ones(len(scores))
    xt=torch.tensor(centered,dtype=torch.float32,device=device)
    yt=torch.tensor(y,dtype=torch.float32,device=device)
    pit=torch.tensor(pidx,dtype=torch.long,device=device)
    at=torch.tensor(safe_logit(anchor),dtype=torch.float32,device=device)
    wt=torch.tensor(sw,dtype=torch.float32,device=device)
    model=RewardModel(len(names)).to(device); opt=torch.optim.Adam(model.parameters(),lr=args.reward_lr)
    best=None; bestloss=1e9; stale=0
    for epoch in range(1,args.reward_epochs+1):
        opt.zero_grad()
        logits=at+(model.effective(pit)*xt).sum(1)
        loss=(F.binary_cross_entropy_with_logits(logits,yt,reduction="none")*wt).mean()
        loss=loss+args.reward_lambda_pattern*model.pattern_raw.pow(2).mean()+args.reward_lambda_global*model.global_raw.pow(2).mean()
        loss.backward(); opt.step(); val=float(loss.detach().cpu())
        if val<bestloss-1e-6:
            bestloss=val; best={k:v.detach().cpu().clone() for k,v in model.state_dict().items()}; stale=0
        else: stale+=1
        if args.verbose_reward_training and (epoch==1 or epoch%50==0):
            print(f"[reward] epoch={epoch} loss={val:.6f}")
        if stale>=30: break
    if best is not None: model.load_state_dict(best)
    with torch.no_grad():
        gw=model.global_weights().cpu().numpy(); pm=model.multipliers().cpu().numpy()
    return RewardArtifacts(gw,pm,means,names,pmap,base_rates)

def reward_predict(scores,variant,art):
    x=construct_matrix(scores,variant); pats=scores.hbm8_pattern.astype(str).tolist()
    pidx=np.array([art.pmap[p] for p in pats]); centered=x-art.pattern_means[pidx]
    eff=art.global_weights[None,:]*art.pattern_multipliers[pidx]; contrib=eff*centered
    anchor=np.array([art.base_rates.get(p,art.base_rates["__overall__"])["smoothed_rate"] for p in pats])
    prob=100*sigmoid(safe_logit(anchor)+contrib.sum(1))
    out=pd.DataFrame(index=scores.index)
    out["pattern_base_probability"]=100*anchor
    out["reward_prior_probability"]=prob
    out["reward_adjustment_from_pattern"]=out.reward_prior_probability-out.pattern_base_probability
    for k,name in enumerate(CONSTRUCT_NAMES):
        out[f"reward_contribution_{name}"]=contrib[:,k]
        out[f"reward_effective_weight_{name}"]=eff[:,k]
    return out

def make_folds(memory,folds,seed):
    strata=memory.vaccinated.astype(int).astype(str)+"|"+memory.hbm8_pattern.astype(str)
    vc=strata.value_counts(); rare=set(vc[vc<folds].index)
    strata=strata.where(~strata.isin(rare),memory.vaccinated.astype(int).astype(str))
    ns=max(2,min(folds,int(strata.value_counts().min())))
    skf=StratifiedKFold(n_splits=ns,shuffle=True,random_state=seed)
    return list(skf.split(np.arange(len(memory)),strata))

def crossfit_reward(memory,variant,args,device):
    out=pd.DataFrame(index=memory.index)
    for fold,(tr,va) in enumerate(make_folds(memory,args.reward_oof_folds,args.random_seed),1):
        train=memory.iloc[tr]; val=memory.iloc[va]
        br=fit_base_rates(train,args.base_rate_prior_strength)
        art=fit_reward_model(train,br,variant,args,device)
        pr=reward_predict(val,variant,art); pr["reward_oof_fold"]=fold
        out.loc[val.index,pr.columns]=pr
    return out


