def build_profile(raw_row,s,variant,v4,v5,include_sensitive):
    if variant=="v4":
        return v4.build_full_observed_profile(
            raw_row=raw_row, score_row=s, include_sensitive_context=include_sensitive
        )
    return v5.build_observed_profile(raw_row,s,include_sensitive)

@dataclass
class SimilaritySpace:
    sources: List[int]
    pos: Dict[int,int]
    matrix: np.ndarray
    patterns: Dict[int,str]
    def similarity(self,q,m):
        qi=self.pos.get(int(q)); mi=self.pos.get(int(m))
        if qi is None or mi is None: return 0.
        return float(np.clip(np.dot(self.matrix[qi],self.matrix[mi]),-1,1))

def fit_similarity(scores,variant,fit_sources=None):
    common=[
        "observed_threat_proxy","structural_barrier_proxy","healthcare_cue_proxy",
        "navigation_self_efficacy_proxy","motivation_score","capability_score","activation_score",
        "chronic_or_risk_count","threat_age_component","threat_health_component",
        "threat_chronic_component","threat_function_component","threat_immune_component",
        "barrier_insurance_component","barrier_cost_care_component","barrier_financial_component",
        "barrier_transport_component","barrier_communication_component",
        "cue_doctor_component","cue_retail_virtual_component","cue_acute_component",
        "selfeff_usual_care_component","selfeff_care_setting_component",
        "selfeff_internet_component","selfeff_virtual_component","selfeff_communication_component",
    ]
    if variant=="v4":
        extra=["vaccine_acceptance_benefit_proxy","benefit_covid_component",
               "benefit_pneumonia_component","benefit_shingles_component"]
    else:
        extra=["preventive_engagement_proxy","engagement_wellness_component",
               "engagement_information_component","engagement_doctor_communication_component",
               "engagement_result_review_component"]
    nums=[c for c in common+extra if c in scores.columns]
    cats=[c for c in ["SEX_A","EDUCP_A","RATCAT_A","REGION","BMICAT_A","SMKCIGST_A"] if c in scores.columns]
    frame=scores[nums+cats].copy()
    for c in nums:
        frame[c]=pd.to_numeric(frame[c],errors="coerce")
        frame[c]=frame[c].fillna(frame[c].median())
    for c in cats: frame[c]=frame[c].astype(str).fillna("missing")
    pre=ColumnTransformer([("num",StandardScaler(),nums),("cat",OneHotEncoder(handle_unknown="ignore"),cats)])
    if fit_sources is None:
        fit_frame=frame
    else:
        fit_idx=[i for i in fit_sources if i in frame.index]
        fit_frame=frame.loc[fit_idx] if fit_idx else frame
    pre.fit(fit_frame)
    x=pre.transform(frame)
    if hasattr(x,"toarray"): x=x.toarray()
    x=np.asarray(x,dtype=np.float32); n=np.linalg.norm(x,axis=1,keepdims=True); x=x/np.where(n>0,n,1)
    src=scores.source_row_index.astype(int).tolist()
    return SimilaritySpace(src,{s:i for i,s in enumerate(src)},x,
                           dict(zip(src,scores.hbm8_pattern.astype(str))))

