def usage_from_response(r):
    u=getattr(r,"usage",None)
    if u is None: return {"input_tokens":0,"output_tokens":0,"total_tokens":0}
    i=int(getattr(u,"prompt_tokens",0) or getattr(u,"input_tokens",0) or 0)
    o=int(getattr(u,"completion_tokens",0) or getattr(u,"output_tokens",0) or 0)
    return {"input_tokens":i,"output_tokens":o,"total_tokens":int(getattr(u,"total_tokens",i+o) or i+o)}

def extract_json(text):
    t=re.sub(r"```(?:json)?","",str(text or ""),flags=re.I).replace("```","").strip()
    try:
        o=json.loads(t)
        if isinstance(o,dict): return o
    except Exception: pass
    dec=json.JSONDecoder(); cand=[]
    for m in re.finditer(r"\{",t):
        try:
            o,_=dec.raw_decode(t[m.start():])
            if isinstance(o,dict): cand.append(o)
        except Exception: pass
    if not cand: raise ValueError("no valid JSON object")
    return max(cand,key=lambda x:len(json.dumps(x,ensure_ascii=False)))

async def probe_json_mode(client,model):
    try:
        r=await client.chat.completions.create(
            model=model,messages=[{"role":"system","content":"Return JSON only."},
            {"role":"user","content":'Return {"ok":true}.'}],
            response_format={"type":"json_object"},temperature=0,max_tokens=30)
        return bool(r.choices and extract_json(r.choices[0].message.content))
    except Exception: return False

async def structured_call(client,sem,model,system,prompt,validator,max_tokens,args,json_mode):
    last=""
    use_json=json_mode
    for attempt in range(args.max_retries+1):
        kw={"model":model,"messages":[{"role":"system","content":system},
            {"role":"user","content":prompt+("\nFORMAT RETRY: JSON only; do not echo input." if attempt else "")}],
            "temperature":args.temperature,"max_tokens":max_tokens}
        if use_json: kw["response_format"]={"type":"json_object"}
        try:
            async with sem: r=await client.chat.completions.create(**kw)
            if not r.choices: raise RuntimeError("no choices")
            raw=str(r.choices[0].message.content or "").strip()
            return validator(extract_json(raw)),raw,usage_from_response(r),{
                "attempt_count":attempt+1,"json_mode":bool(use_json),
                "finish_reason":str(getattr(r.choices[0],"finish_reason","") or ""),
                "request_id":str(getattr(r,"_request_id","") or "")}
        except Exception as exc:
            last=f"{type(exc).__name__}: {exc}"
            if "json" in str(exc).lower() or "format" in str(exc).lower(): use_json=False
            if attempt>=args.max_retries: break
            await asyncio.sleep(min(30,2.0*(2**attempt))+random.random())
    raise RuntimeError(f"ASU call failed after {args.max_retries+1} attempts: {last}")

def sample_memory_api_sources(memory_scores, n, seed):
    """Stratified sample for costly memory-building LLM calls; numerical reward fitting still uses full memory."""
    if n <= 0 or n >= len(memory_scores):
        return memory_scores.index.astype(int).tolist()
    frame=memory_scores[["vaccinated","hbm8_pattern"]].copy()
    frame["stratum"]=frame.vaccinated.astype(int).astype(str)+"|"+frame.hbm8_pattern.astype(str)
    counts=frame.stratum.value_counts()
    # proportional allocation with at least one from represented strata when feasible
    alloc={k:max(1,int(round(n*v/len(frame)))) for k,v in counts.items()}
    while sum(alloc.values())>n:
        for k in sorted(alloc,key=lambda z:alloc[z],reverse=True):
            if alloc[k]>1:
                alloc[k]-=1
                if sum(alloc.values())==n: break
        else: break
    while sum(alloc.values())<n:
        changed=False
        for k in counts.index:
            if alloc.get(k,0)<counts[k]:
                alloc[k]=alloc.get(k,0)+1; changed=True
                if sum(alloc.values())==n: break
        if not changed: break
    pieces=[]
    for j,(k,g) in enumerate(frame.groupby("stratum",sort=True)):
        take=min(int(alloc.get(k,0)),len(g))
        if take>0: pieces.extend(g.sample(take,random_state=seed+j).index.astype(int).tolist())
    return sorted(pieces)

def require_success(entries,total,label,min_rate):
    rate=len(entries)/max(1,total)
    print(f"[{label}] success={len(entries)}/{total} ({100*rate:.2f}%)")
    if rate + 1e-12 < min_rate:
        raise RuntimeError(f"{label} coverage {100*rate:.2f}% is below required {100*min_rate:.2f}%")

# ---------------------------------------------------------------------------
# Reward guidance: SILIC-style proposal, numerical acceptance
# ---------------------------------------------------------------------------

REWARD_GUIDE_SYSTEM="""You propose a SMALL theory-constrained update to an external HBM reward integration layer.
All five dimensions are positively oriented toward vaccination:
threat; acceptance_or_engagement; reversed_barrier (higher means fewer barriers); cue; navigation.
Return -1,0,+1 for each. Prefer sparse zeros. Do not change the HBM8 anchor.
Do not invent unobserved beliefs, recommendations, reminders, trust, or intentions.
Your proposal will be accepted only if it improves out-of-fold log loss. JSON only."""

def validate_reward_guide(o):
    src=o.get("update_direction")
    if not isinstance(src,Mapping): raise ValueError("update_direction must be object")
    d={}
    for k in CONSTRUCT_NAMES:
        v=int(round(float(src.get(k,0))))
        if v not in {-1,0,1}: raise ValueError(k)
        d[k]=v
    return {"update_direction":d,"reason":" ".join(str(o.get("reason","")).split())[:500]}

def reward_guide_prompt(pattern,g,current):
    y=g.vaccinated.to_numpy(int); p=g.reward_prior_probability.to_numpy(float)/100
    fp=g[(g.vaccinated==0)&(g.reward_prior_probability>=50)]
    fn=g[(g.vaccinated==1)&(g.reward_prior_probability<50)]
    payload={"pattern":pattern,"n":len(g),"observed_rate":float(y.mean()),
        "mean_predicted_probability":float(p.mean()),
        "mean_observed_minus_predicted":float(np.mean(y-p)),
        "false_positive_rate":len(fp)/max(1,len(g)),"false_negative_rate":len(fn)/max(1,len(g)),
        "current_effective_weights":current,
        "mean_construct_contributions":{k:float(g[f"reward_contribution_{k}"].mean()) for k in CONSTRUCT_NAMES},
        "false_positive_mean_contributions":{k:float(fp[f"reward_contribution_{k}"].mean()) if len(fp) else 0 for k in CONSTRUCT_NAMES},
        "false_negative_mean_contributions":{k:float(fn[f"reward_contribution_{k}"].mean()) if len(fn) else 0 for k in CONSTRUCT_NAMES},
        "required_output":{"update_direction":{k:"-1|0|1" for k in CONSTRUCT_NAMES},"reason":"one sentence"}}
    return json.dumps(payload,ensure_ascii=False,separators=(",",":"))

def candidate_loss(g,vec,step):
    y=g.vaccinated.to_numpy(int); anchor=g.pattern_base_probability.to_numpy(float)/100
    c=np.column_stack([g[f"reward_contribution_{k}"].to_numpy(float) for k in CONSTRUCT_NAMES])
    old=sigmoid(safe_logit(anchor)+c.sum(1))
    new=sigmoid(safe_logit(anchor)+(c*np.exp(step*np.asarray(vec))[None,:]).sum(1))
    return float(log_loss(y,np.clip(old,1e-6,1-1e-6),labels=[0,1])),float(log_loss(y,np.clip(new,1e-6,1-1e-6),labels=[0,1]))

async def guide_pattern_rewards(oof,memory,art,model,client,sem,args,json_mode,log_path,h):
    """LLM sees a guidance subset; acceptance is evaluated on a disjoint OOF validation subset."""
    latest=load_latest(log_path,h,key="pattern_id"); accepted={}
    for p,pid in art.pmap.items():
        idx=memory.index[memory.hbm8_pattern.astype(str)==p]
        g=pd.concat([memory.loc[idx,["vaccinated","hbm8_pattern"]],oof.loc[idx]],axis=1).dropna(subset=["reward_prior_probability"])
        if len(g)<args.reward_revision_min_pattern_n: continue
        if latest.get(pid,{}).get("status")=="ok":
            if latest[pid].get("accepted"): accepted[p]=latest[pid]["direction_vector"]
            continue
        # Disjoint guidance/validation split within this pattern. OOF predictions themselves
        # are already cross-fitted, and the final accept/reject decision is not made on
        # the same rows summarized to the LLM.
        pos=np.arange(len(g)); y=g.vaccinated.astype(int).to_numpy()
        try:
            guide_pos,val_pos=train_test_split(
                pos,test_size=args.reward_revision_validation_fraction,
                random_state=args.random_seed+pid,
                stratify=y if len(np.unique(y))>1 and np.min(np.bincount(y))>=2 else None,
            )
        except Exception:
            cut=max(1,int(round(len(g)*(1-args.reward_revision_validation_fraction))))
            guide_pos,val_pos=pos[:cut],pos[cut:]
        g_guide=g.iloc[guide_pos]; g_val=g.iloc[val_pos] if len(val_pos) else g.iloc[guide_pos]
        current=art.global_weights*art.pattern_multipliers[pid]
        try:
            val,raw,u,meta=await structured_call(client,sem,model,REWARD_GUIDE_SYSTEM,
                reward_guide_prompt(p,g_guide,{k:float(v) for k,v in zip(CONSTRUCT_NAMES,current)}),
                validate_reward_guide,args.reward_revision_max_tokens,args,json_mode)
            vec=[val["update_direction"][k] for k in CONSTRUCT_NAMES]
            old,new=candidate_loss(g_val,vec,args.reward_revision_step)
            ok=new+args.reward_revision_min_gain<old
            e={"created_at":utc_now(),"config_hash":h,"status":"ok","pattern_id":pid,"pattern":p,
               "direction_vector":vec,"direction_by_name":val["update_direction"],"reason":val["reason"],
               "guidance_n":len(g_guide),"validation_n":len(g_val),
               "validation_old_log_loss":old,"validation_candidate_log_loss":new,"gain":old-new,"accepted":ok,
               "usage":u,"call_meta":meta,"raw_response":raw}
            append_jsonl(log_path,e); latest[pid]=e
            if ok: accepted[p]=vec
        except Exception as exc:
            append_jsonl(log_path,{"created_at":utc_now(),"config_hash":h,"status":"error",
                         "pattern_id":pid,"pattern":p,"error":str(exc)})
    return accepted

def apply_revision_to_art(art,accepted,step):
    for p,vec in accepted.items():
        art.pattern_multipliers[art.pmap[p]]*=np.exp(step*np.asarray(vec,dtype=float))
    return art

def apply_revision_to_oof(oof,memory,accepted,step):
    out=oof.copy()
    for p,vec in accepted.items():
        mask=memory.hbm8_pattern.astype(str)==p
        fac=np.exp(step*np.asarray(vec,dtype=float))
        for j,k in enumerate(CONSTRUCT_NAMES):
            out.loc[mask,f"reward_contribution_{k}"]*=fac[j]
            out.loc[mask,f"reward_effective_weight_{k}"]*=fac[j]
        anchor=out.loc[mask,"pattern_base_probability"].to_numpy(float)/100
        c=np.column_stack([out.loc[mask,f"reward_contribution_{k}"].to_numpy(float) for k in CONSTRUCT_NAMES])
        out.loc[mask,"reward_prior_probability"]=100*sigmoid(safe_logit(anchor)+c.sum(1))
        out.loc[mask,"reward_adjustment_from_pattern"]=out.loc[mask,"reward_prior_probability"]-out.loc[mask,"pattern_base_probability"]
    return out

# ---------------------------------------------------------------------------
# Decision / reflection
# ---------------------------------------------------------------------------

DECISION_SYSTEM="""You are a public-health behavioral analyst using an HBM-inspired framework.
Use the REWARD-CALIBRATED HBM prior as the primary numeric anchor. The HBM8 pattern rate is shown for context.
Do not recompute construct weights from scratch. Use raw observed evidence and applicable memories only for a SMALL residual correction.
Memory empirical Q-value means that the rule's correction direction historically reduced log loss among similar memory-split cases.
A memory is not a label: apply only when applicability conditions match and contradiction conditions do not.
These are observed proxies, not psychometric beliefs. Never invent physician recommendations, reminders, trust, intentions, or private attitudes.
Final probability must equal reward_prior_probability + residual_adjustment, clipped 0-100. JSON only."""

REFLECTION_SYSTEM="""Build one reusable reflective memory from a high-confidence RG-FLARE-VAX error.
Diagnose one failure stage: construct_scoring, reward_weighting, pattern_anchor, residual_reasoning, or memory_misapplication.
Ground every statement in supplied observed variables. Do not invent beliefs, recommendations, reminders, trust, or intentions.
Return applicability conditions, contradiction conditions, retrieval keys, and one concise correction rule. JSON only."""

def decision_prompt(profile,r,memories,args):
    mp=[]
    for m in memories:
        mp.append({"retrieval_score":round(m["retrieval_score"],4),"similarity":round(m["similarity"],4),
            "same_pattern":m["same_pattern"],"empirical_q_value":round(m.get("empirical_q_value",0),6),
            "reward_support_n":m.get("reward_support_n",0),"correction_direction":m["correction_direction"],
            "failure_stage":m.get("failure_stage"),"correction_rule":m["correction_rule"],
            "applicability_conditions":m["applicability_conditions"],
            "contradiction_conditions":m.get("contradiction_conditions",[]),
            "supporting_variables":m.get("supporting_variables",[])})
    payload={"training_pattern_anchor":{"pattern":profile.get("hbm8_pattern"),
        "general_tendency":PATTERN_TENDENCY.get(str(profile.get("hbm8_pattern"))),
        "base_probability_yes":round(float(r.pattern_base_probability),2)},
        "reward_calibrated_hbm_prior":{"probability_yes":round(float(r.reward_prior_probability),2),
        "adjustment_from_pattern":round(float(r.reward_adjustment_from_pattern),2),
        "construct_contributions_to_logit":{k:round(float(r[f"reward_contribution_{k}"]),4) for k in CONSTRUCT_NAMES},
        "effective_construct_weights":{k:round(float(r[f"reward_effective_weight_{k}"]),4) for k in CONSTRUCT_NAMES}},
        "respondent_observed_profile":profile,"retrieved_reward_valued_memories":mp,
        "required_output":{"reward_prior_check":"mostly_consistent|adjust_up|adjust_down",
        "residual_adjustment":f"integer [-{args.max_residual_adjustment},{args.max_residual_adjustment}]",
        "probability_yes":"0-100","dominant_observed_factors":"array 2-6",
        "memory_application":"array up to 3","exception_or_contradiction":"text",
        "reason":"concise paragraph","confidence":"0-1"}}
    return json.dumps(payload,ensure_ascii=False,separators=(",",":"))

def validate_decision(o,reward_prior,args):
    a=max(-args.max_residual_adjustment,min(args.max_residual_adjustment,int(round(float(o.get("residual_adjustment",0))))))
    p=float(np.clip(reward_prior+a,0,100)); raw=float(o.get("probability_yes",p))
    return {"reward_prior_check":str(o.get("reward_prior_check","mostly_consistent"))[:80],
        "residual_adjustment":a,"raw_probability_yes":raw,"probability_yes":p,
        "probability_consistency_corrected":abs(raw-p)>1,
        "dominant_observed_factors":[str(x)[:160] for x in o.get("dominant_observed_factors",[])][:6],
        "memory_application":[str(x)[:180] for x in o.get("memory_application",[])][:3],
        "exception_or_contradiction":" ".join(str(o.get("exception_or_contradiction","")).split())[:400],
        "reason":" ".join(str(o.get("reason","")).split())[:600],
        "confidence":float(np.clip(float(o.get("confidence",.5)),0,1))}

def expected_correction(actual,p):
    if actual==1 and p<50: return "increase","underprediction"
    if actual==0 and p>=50: return "decrease","overprediction"
    raise ValueError("not an error")

def reflection_prompt(profile,r,d,actual,direction,error_type):
    payload={"actual_outcome":"YES" if actual else "NO","required_correction_direction":direction,
        "required_error_type":error_type,
        "reward_anchor":{"pattern_base_probability":float(r.pattern_base_probability),
        "reward_prior_probability":float(r.reward_prior_probability),
        "construct_contributions":{k:float(r[f"reward_contribution_{k}"]) for k in CONSTRUCT_NAMES}},
        "wrong_no_memory_decision":{"residual_adjustment":d["residual_adjustment"],
        "probability_yes":d["probability_yes"],"dominant_observed_factors":d["dominant_observed_factors"],
        "reason":d["reason"]},"respondent_observed_profile":profile,
        "required_output":{"correction_direction":direction,"error_type":error_type,
        "failure_stage":"construct_scoring|reward_weighting|pattern_anchor|residual_reasoning|memory_misapplication",
        "incorrect_assumption":"text","supporting_variables":"array 2-7","correction_rule":"text",
        "applicability_conditions":"array 1-6","contradiction_conditions":"array 1-5",
        "retrieval_keys":"array 2-8","reflection_confidence":"0-1","estimated_memory_value":"0-1"}}
    return json.dumps(payload,ensure_ascii=False,separators=(",",":"))

def validate_reflection(o,direction,error_type):
    if str(o.get("correction_direction"))!=direction or str(o.get("error_type"))!=error_type:
        raise ValueError("reflection direction/type mismatch")
    stage=str(o.get("failure_stage","residual_reasoning"))
    allowed={"construct_scoring","reward_weighting","pattern_anchor","residual_reasoning","memory_misapplication"}
    if stage not in allowed: stage="residual_reasoning"
    sv=[str(x)[:180] for x in o.get("supporting_variables",[]) if str(x).strip()][:7]
    if len(sv)<2: raise ValueError("need >=2 supporting variables")
    return {"correction_direction":direction,"error_type":error_type,"failure_stage":stage,
        "incorrect_assumption":" ".join(str(o.get("incorrect_assumption","")).split())[:350],
        "supporting_variables":sv,"correction_rule":" ".join(str(o.get("correction_rule","")).split())[:500],
        "applicability_conditions":[str(x)[:180] for x in o.get("applicability_conditions",[])][:6],
        "contradiction_conditions":[str(x)[:180] for x in o.get("contradiction_conditions",[])][:5],
        "retrieval_keys":[str(x)[:100] for x in o.get("retrieval_keys",[])][:8],
        "reflection_confidence":float(np.clip(float(o.get("reflection_confidence",.5)),0,1)),
        "estimated_memory_value":float(np.clip(float(o.get("estimated_memory_value",.5)),0,1))}


# ---------------------------------------------------------------------------
# Memory Q-value
# ---------------------------------------------------------------------------

def err_conf(actual,p): return max(0,(50-p)/50) if actual==1 else max(0,(p-50)/50)

def select_reflections(entries,args):
    cand=[]
    for e in entries:
        if e.get("status")!="ok": continue
        y=int(e["actual"]); p=float(e["decision"]["probability_yes"])
        wrong=(y==1 and p<50) or (y==0 and p>=50)
        if not wrong: continue
        ec=err_conf(y,p)
        if ec>=args.min_error_confidence:
            x=dict(e); x["error_confidence"]=ec; cand.append(x)
    cand.sort(key=lambda z:z["error_confidence"],reverse=True)
    return cand[:args.max_reflection_candidates]

def token_set(m):
    t=(str(m.get("correction_rule",""))+" "+" ".join(map(str,m.get("retrieval_keys",[])))+
       " "+" ".join(map(str,m.get("supporting_variables",[])))).lower()
    return set(re.findall(r"[a-z0-9_]+",t))

def distill_memories(reflections,args):
    prelim=[]
    for e in reflections:
        if e.get("status")!="ok": continue
        r=e["reflection"]
        if r["reflection_confidence"]<args.min_reflection_confidence or r["estimated_memory_value"]<args.min_estimated_memory_value: continue
        spec=min(1,len(r["supporting_variables"])/4)
        val=.35*e.get("error_confidence",0)+.25*spec+.2*r["reflection_confidence"]+.2*r["estimated_memory_value"]
        prelim.append({"source_row_index":int(e["source_row_index"]),"pattern":e["pattern"],
            **r,"memory_value_prior":float(np.clip(val,0,1))})
    kept=[]
    for m in sorted(prelim,key=lambda x:x["memory_value_prior"],reverse=True):
        tok=token_set(m)
        if any(m["correction_direction"]==k["correction_direction"] and
               len(tok&token_set(k))/max(1,len(tok|token_set(k)))>=args.memory_dedup_jaccard for k in kept):
            continue
        kept.append(m)
    for i,m in enumerate(kept,1): m["memory_id"]=f"M{i:05d}"
    return kept

def one_logloss(y,pct):
    p=np.clip(pct/100,1e-6,1-1e-6)
    return -(y*math.log(p)+(1-y)*math.log(1-p))

def value_memories(memories,train_entries,sim,args):
    by={int(e["source_row_index"]):e for e in train_entries if e.get("status")=="ok"}
    for m in memories:
        src=int(m["source_row_index"]); neigh=[]
        for q,e in by.items():
            if q==src: continue
            s=sim.similarity(q,src)
            if s>=args.memory_q_min_similarity: neigh.append((s,e))
        neigh=sorted(neigh,key=lambda z:z[0],reverse=True)[:args.memory_q_max_neighbors]
        rewards=[]; weights=[]; signs=[]; d=1 if m["correction_direction"]=="increase" else -1
        for s,e in neigh:
            y=int(e["actual"]); p0=float(e["decision"]["probability_yes"]); p1=np.clip(p0+d*args.memory_q_counterfactual_step*s,0,100)
            rr=one_logloss(y,p0)-one_logloss(y,p1)
            rewards.append(rr); weights.append(s*s); signs.append(np.sign(rr))
        if rewards:
            mean=float(np.average(rewards,weights=weights)); n=len(rewards)
            q=n/(n+args.memory_q_shrink_kappa)*mean
            pos=float(np.mean(np.array(signs)>0)); harm=float(np.mean(np.array(signs)<0))
        else: mean=q=pos=harm=0.; n=0
        m.update({"empirical_reward_mean":mean,"empirical_q_value":float(q),"reward_support_n":n,
                  "empirical_positive_rate":pos,"empirical_harmful_rate":harm})
    return memories

@dataclass
class MemoryStore:
    memories: List[Dict[str,Any]]
    sim: SimilaritySpace
    args: Any
    def retrieve(self,source):
        qp=self.sim.patterns.get(int(source),""); scored=[]
        for m in self.memories:
            q=float(m.get("empirical_q_value",0))
            if q<self.args.memory_min_empirical_q: continue
            same=str(m.get("pattern"))==qp
            if self.args.memory_same_pattern_only and not same: continue
            s=self.sim.similarity(source,int(m["source_row_index"]))
            if s<self.args.memory_min_similarity: continue
            qn=.5+.5*math.tanh(q/max(1e-6,self.args.memory_q_tau))
            score=.60*s+.20*qn+.10*float(m.get("memory_value_prior",0))+.10*float(same)
            e=dict(m); e.update({"similarity":s,"same_pattern":same,"q_normalized":qn,"retrieval_score":score})
            scored.append((score,e))
        scored.sort(key=lambda x:x[0],reverse=True)
        if not self.args.memory_direction_diversity: return [e for _,e in scored[:self.args.memory_top_k]]
        out=[]; used=set()
        for _,e in scored:
            d=e["correction_direction"]
            if d not in used: out.append(e); used.add(d)
            if len(out)>=self.args.memory_top_k: return out
        for _,e in scored:
            if e not in out: out.append(e)
            if len(out)>=self.args.memory_top_k: break
        return out

# ---------------------------------------------------------------------------
# Async phases
# ---------------------------------------------------------------------------

async def decision_case(source,phase,raw,scores,reward,variant,v4,v5,model,client,sem,json_mode,args,store,h):
    s=scores.loc[source]; r=reward.loc[source]
    profile=build_profile(raw.loc[source],s,variant,v4,v5,args.include_sensitive_context)
    memories=store.retrieve(source) if store else []
    try:
        val,rawtxt,u,meta=await structured_call(client,sem,model,DECISION_SYSTEM,
            decision_prompt(profile,r,memories,args),
            lambda o:validate_decision(o,float(r.reward_prior_probability),args),
            args.decision_max_tokens,args,json_mode)
        return {"created_at":utc_now(),"config_hash":h,"status":"ok","phase":phase,"variant":variant,"model":model,
            "source_row_index":int(source),"actual":int(s.vaccinated),"pattern":str(s.hbm8_pattern),
            "pattern_base_probability":float(r.pattern_base_probability),"reward_prior_probability":float(r.reward_prior_probability),
            "reward_adjustment_from_pattern":float(r.reward_adjustment_from_pattern),
            "reward_contributions":{k:float(r[f"reward_contribution_{k}"]) for k in CONSTRUCT_NAMES},
            "decision":val,"retrieved_memory_ids":[m["memory_id"] for m in memories],
            "usage":u,"call_meta":meta,"raw_response":rawtxt}
    except Exception as exc:
        return {"created_at":utc_now(),"config_hash":h,"status":"error","phase":phase,"variant":variant,"model":model,
            "source_row_index":int(source),"actual":int(s.vaccinated),"pattern":str(s.hbm8_pattern),
            "error_type":type(exc).__name__,"error_message":str(exc)}

async def decision_batch(sources,label,log,latest,raw,scores,reward,variant,v4,v5,model,client,sem,json_mode,args,store,h):
    pending=[int(i) for i in sources if latest.get(int(i),{}).get("status")!="ok"]
    print(f"[{variant}/{model}/{label}] total={len(sources)} reused_ok={len(sources)-len(pending)} calls={len(pending)}")
    done=0
    for start in range(0,len(pending),max(1,args.concurrent_samples)):
        chunk=pending[start:start+max(1,args.concurrent_samples)]
        rr=await asyncio.gather(*[decision_case(i,label,raw,scores,reward,variant,v4,v5,model,client,sem,json_mode,args,store,h) for i in chunk])
        for e in rr:
            latest[int(e["source_row_index"])]=e; append_jsonl(log,e); done+=1
        if done==len(pending) or done%args.progress_every<len(chunk):
            ok=sum(latest.get(int(i),{}).get("status")=="ok" for i in sources)
            print(f"[{variant}/{model}/{label}] {done}/{len(pending)} new complete | ok={ok}")
    return [latest[int(i)] for i in sources if latest.get(int(i),{}).get("status")=="ok"]

async def reflection_case(e,raw,scores,reward,variant,v4,v5,model,client,sem,json_mode,args,h):
    src=int(e["source_row_index"]); y=int(e["actual"]); p=float(e["decision"]["probability_yes"])
    d,et=expected_correction(y,p); prof=build_profile(raw.loc[src],scores.loc[src],variant,v4,v5,args.include_sensitive_context)
    try:
        val,rawtxt,u,meta=await structured_call(client,sem,model,REFLECTION_SYSTEM,
            reflection_prompt(prof,reward.loc[src],e["decision"],y,d,et),
            lambda o:validate_reflection(o,d,et),args.reflection_max_tokens,args,json_mode)
        return {"created_at":utc_now(),"config_hash":h,"status":"ok","variant":variant,"model":model,
            "source_row_index":src,"actual":y,"pattern":e["pattern"],"error_confidence":e["error_confidence"],
            "reflection":val,"usage":u,"call_meta":meta,"raw_response":rawtxt}
    except Exception as exc:
        return {"created_at":utc_now(),"config_hash":h,"status":"error","variant":variant,"model":model,
            "source_row_index":src,"actual":y,"pattern":e["pattern"],"error_confidence":e["error_confidence"],
            "error_type":type(exc).__name__,"error_message":str(exc)}

async def reflection_batch(candidates,log,latest,raw,scores,reward,variant,v4,v5,model,client,sem,json_mode,args,h):
    pending=[e for e in candidates if latest.get(int(e["source_row_index"]),{}).get("status")!="ok"]
    print(f"[{variant}/{model}/reflections] total={len(candidates)} reused_ok={len(candidates)-len(pending)} calls={len(pending)}")
    done=0
    for start in range(0,len(pending),max(1,args.concurrent_samples)):
        chunk=pending[start:start+max(1,args.concurrent_samples)]
        rr=await asyncio.gather(*[reflection_case(e,raw,scores,reward,variant,v4,v5,model,client,sem,json_mode,args,h) for e in chunk])
        for e in rr:
            latest[int(e["source_row_index"])]=e; append_jsonl(log,e); done+=1
        if done==len(pending) or done%args.progress_every<len(chunk):
            print(f"[{variant}/{model}/reflections] {done}/{len(pending)} new complete")
    return [latest[int(e["source_row_index"])] for e in candidates if latest.get(int(e["source_row_index"]),{}).get("status")=="ok"]

# ---------------------------------------------------------------------------
# Metrics / output
# ---------------------------------------------------------------------------

def metrics(y,pct,t,sw=None):
    y=np.asarray(y,int); pct=np.asarray(pct,float); p=np.clip(pct/100,1e-6,1-1e-6); pred=(pct>=t).astype(int)
    cm=confusion_matrix(y,pred,labels=[0,1],sample_weight=sw); tn,fp,fn,tp=cm.ravel()
    try: auc=roc_auc_score(y,p,sample_weight=sw)
    except: auc=np.nan
    try: ap=average_precision_score(y,p,sample_weight=sw)
    except: ap=np.nan
    return {"n":len(y),"threshold":float(t),"accuracy":accuracy_score(y,pred,sample_weight=sw),
        "balanced_accuracy":balanced_accuracy_score(y,pred,sample_weight=sw),
        "precision":precision_score(y,pred,sample_weight=sw,zero_division=0),
        "recall":recall_score(y,pred,sample_weight=sw,zero_division=0),
        "specificity":float(tn/max(1e-12,tn+fp)),"f1":f1_score(y,pred,sample_weight=sw,zero_division=0),
        "roc_auc":auc,"average_precision":ap,"brier":brier_score_loss(y,p,sample_weight=sw),
        "log_loss":log_loss(y,p,sample_weight=sw,labels=[0,1])}

def calibrate(y,pct,name):
    rows=[]
    for t in range(5,96):
        pred=(pct>=t).astype(int)
        s=(balanced_accuracy_score(y,pred) if name=="balanced_accuracy" else
           f1_score(y,pred,zero_division=0) if name=="f1" else accuracy_score(y,pred))
        rows.append({"threshold":t,name:s})
    df=pd.DataFrame(rows); b=df.sort_values([name,"threshold"],ascending=[False,True]).iloc[0]
    return float(b.threshold),df

def entries_df(entries):
    rows=[]
    for e in entries:
        row={k:e.get(k) for k in ["source_row_index","status","actual","pattern","pattern_base_probability",
                                  "reward_prior_probability","reward_adjustment_from_pattern"]}
        if e.get("status")=="ok":
            row.update({"probability_yes":e["decision"]["probability_yes"],
                        "residual_adjustment":e["decision"]["residual_adjustment"],
                        "confidence":e["decision"]["confidence"],
                        "retrieved_memory_ids":"|".join(e.get("retrieved_memory_ids",[]))})
        else: row.update({"error_type":e.get("error_type"),"error_message":e.get("error_message")})
        rows.append(row)
    return pd.DataFrame(rows)

