# Per variant/model pipeline
# ---------------------------------------------------------------------------

async def run_one(raw,scores,assignments,thresholds,base_rates,variant,v4,v5,model,root,client,sem,json_mode,args,device):
    d=root/variant/model
    if args.overwrite and d.exists(): shutil.rmtree(d)
    (d/"logs").mkdir(parents=True,exist_ok=True)
    memsrc=assignments.loc[assignments.split=="memory","source_row_index"].astype(int).tolist()
    calsrc=assignments.loc[assignments.split=="calibration","source_row_index"].astype(int).tolist()
    testsrc=assignments.loc[assignments.split=="test","source_row_index"].astype(int).tolist()
    memory=scores.loc[memsrc]
    api_memsrc=sample_memory_api_sources(memory,args.memory_api_sample_size,args.random_seed+701)
    print(f"[{variant}/{model}] numerical_memory={len(memsrc):,} reflection_api_memory={len(api_memsrc):,}")

    print(f"[{variant}/{model}] cross-fitting numerical reward prior...")
    oof_path=d/"reward_oof_memory.csv"
    if oof_path.exists() and not args.overwrite:
        oof=pd.read_csv(oof_path,index_col=0); oof.index=oof.index.astype(int)
    else:
        oof=crossfit_reward(memory,variant,args,device); oof.to_csv(oof_path)
    art=fit_reward_model(memory,base_rates,variant,args,device)

    accepted={}
    guide_hash=cfg_hash({"version":REWARD_GUIDE_VERSION,"variant":variant,"model":args.reward_guide_model or model,
                         "step":args.reward_revision_step,"min_gain":args.reward_revision_min_gain,
                         "memory_sha":hashlib.sha256(json.dumps(memsrc).encode()).hexdigest()})
    if args.llm_reward_revision:
        accepted=await guide_pattern_rewards(oof,memory,art,args.reward_guide_model or model,client,sem,args,json_mode,
                                             d/"logs"/"pattern_reward_guidance.jsonl",guide_hash)
        art=apply_revision_to_art(art,accepted,args.reward_revision_step)
        oof=apply_revision_to_oof(oof,memory,accepted,args.reward_revision_step)
    reward=reward_predict(scores,variant,art)
    for c in oof.columns: reward.loc[memsrc,c]=oof.loc[memsrc,c]
    reward.to_csv(d/"reward_priors_all_selected.csv")
    weights=[]
    for p,pid in art.pmap.items():
        eff=art.global_weights*art.pattern_multipliers[pid]
        weights.append({"pattern":p,**{f"weight_{k}":float(v) for k,v in zip(CONSTRUCT_NAMES,eff)},
                        "accepted_llm_direction":json.dumps(accepted.get(p,[]))})
    pd.DataFrame(weights).to_csv(d/"reward_effective_weights.csv",index=False)

    sim=fit_similarity(scores,variant,memsrc)
    stable={"version":VERSION,"prompt_version":PROMPT_VERSION,"variant":variant,"model":model,
        "memory_sha":hashlib.sha256(json.dumps(memsrc).encode()).hexdigest(),
        "reflection_memory_sha":hashlib.sha256(json.dumps(api_memsrc).encode()).hexdigest(),
        "reward_params":{"folds":args.reward_oof_folds,"epochs":args.reward_epochs,"lr":args.reward_lr,
                         "lp":args.reward_lambda_pattern,"lg":args.reward_lambda_global},
        "accepted_reward_guidance":accepted,"max_residual_adjustment":args.max_residual_adjustment,
        "memory_params":{"top_k":args.memory_top_k,"min_similarity":args.memory_min_similarity,
                         "q_step":args.memory_q_counterfactual_step,"q_tau":args.memory_q_tau,
                         "min_q":args.memory_min_empirical_q}}
    h=cfg_hash(stable); (d/"run_config.json").write_text(json.dumps(stable,ensure_ascii=False,indent=2),encoding="utf-8")

    trainlog=d/"logs"/"memory_no_memory.jsonl"; trainlatest=load_latest(trainlog,h)
    train=await decision_batch(api_memsrc,"memory_no_memory",trainlog,trainlatest,raw,scores,reward,variant,v4,v5,model,client,sem,json_mode,args,None,h)
    require_success(train,len(api_memsrc),f"{variant}/{model}/memory_no_memory",args.min_success_rate)
    cand=select_reflections(train,args)
    pd.DataFrame([{"source_row_index":e["source_row_index"],"pattern":e["pattern"],"actual":e["actual"],
                   "probability_yes":e["decision"]["probability_yes"],"error_confidence":e["error_confidence"]} for e in cand]
                ).to_csv(d/"reflection_candidates.csv",index=False)
    rlog=d/"logs"/"reflections.jsonl"; rlatest=load_latest(rlog,h)
    refs=await reflection_batch(cand,rlog,rlatest,raw,scores,reward,variant,v4,v5,model,client,sem,json_mode,args,h)
    memories=distill_memories(refs,args); memories=value_memories(memories,train,sim,args)
    with (d/"memory_final_reward_valued.jsonl").open("w",encoding="utf-8") as f:
        for m in memories: f.write(json.dumps(m,ensure_ascii=False,default=str)+"\n")
    pd.DataFrame(memories).to_csv(d/"memory_final_reward_valued.csv",index=False)
    store=MemoryStore(memories,sim,args)

    callog=d/"logs"/"calibration_with_memory.jsonl"; callatest=load_latest(callog,h)
    cal=await decision_batch(calsrc,"calibration_with_memory",callog,callatest,raw,scores,reward,variant,v4,v5,model,client,sem,json_mode,args,store,h)
    require_success(cal,len(calsrc),f"{variant}/{model}/calibration_with_memory",args.min_success_rate)
    if not cal: raise RuntimeError("No successful calibration calls")
    yc=np.array([e["actual"] for e in cal]); pc=np.array([e["decision"]["probability_yes"] for e in cal])
    rc=np.array([e["reward_prior_probability"] for e in cal])
    bc=np.array([e["pattern_base_probability"] for e in cal])
    t,tdf=calibrate(yc,pc,args.threshold_metric); rt,rdf=calibrate(yc,rc,args.threshold_metric)
    bt,bdf=calibrate(yc,bc,args.threshold_metric)
    tdf.to_csv(d/"threshold_search_final.csv",index=False); rdf.to_csv(d/"threshold_search_reward.csv",index=False)
    bdf.to_csv(d/"threshold_search_pattern_anchor.csv",index=False)

    tlog=d/"logs"/"test_with_memory.jsonl"; tlatest=load_latest(tlog,h)
    test=await decision_batch(testsrc,"test_with_memory",tlog,tlatest,raw,scores,reward,variant,v4,v5,model,client,sem,json_mode,args,store,h)
    require_success(test,len(testsrc),f"{variant}/{model}/test_with_memory",args.min_success_rate)
    nm=[]
    if args.run_test_without_memory:
        nlog=d/"logs"/"test_without_memory.jsonl"; nlatest=load_latest(nlog,h)
        nm=await decision_batch(testsrc,"test_without_memory",nlog,nlatest,raw,scores,reward,variant,v4,v5,model,client,sem,json_mode,args,None,h)
    y=np.array([e["actual"] for e in test]); p=np.array([e["decision"]["probability_yes"] for e in test])
    rp=np.array([e["reward_prior_probability"] for e in test]); pb=np.array([e["pattern_base_probability"] for e in test])
    sw=np.array([float(scores.loc[e["source_row_index"],"survey_weight"]) for e in test])
    good=np.isfinite(sw)&(sw>0); sw=np.where(good,sw,np.nanmedian(sw[good]) if good.any() else 1)
    met={"pattern_anchor":metrics(y,pb,bt),"reward_prior":metrics(y,rp,rt),
         "final_reward_memory":metrics(y,p,t),"final_reward_memory_survey_weighted":metrics(y,p,t,sw)}
    if nm:
        met["final_without_memory"]=metrics(np.array([e["actual"] for e in nm]),
                                            np.array([e["decision"]["probability_yes"] for e in nm]),t)
    entries_df(train).to_csv(d/"memory_no_memory_predictions.csv",index=False)
    entries_df(cal).to_csv(d/"calibration_predictions_with_memory.csv",index=False)
    entries_df(test).to_csv(d/"test_predictions_with_memory.csv",index=False)
    if nm: entries_df(nm).to_csv(d/"test_predictions_without_memory.csv",index=False)
    summary={"version":VERSION,"created_at":utc_now(),"variant":variant,"model":model,
             "split_sizes":{"memory":len(memsrc),"reflection_api_memory":len(api_memsrc),"calibration":len(calsrc),"test":len(testsrc)},
             "thresholds":thresholds,"accepted_pattern_reward_guidance":accepted,
             "n_reflection_candidates":len(cand),"n_final_memories":len(memories),
             "memory_q_mean":float(np.mean([m.get("empirical_q_value",0) for m in memories])) if memories else 0,
             "final_threshold":t,"reward_threshold":rt,"pattern_anchor_threshold":bt,"metrics":met}
    (d/"summary.json").write_text(json.dumps(summary,ensure_ascii=False,indent=2,default=str),encoding="utf-8")
    return summary

def build_parser():
    p=argparse.ArgumentParser()
    p.add_argument("--input-csv",required=True); p.add_argument("--output-dir",required=True)
    p.add_argument("--v4-script",default="",help="Optional override of embedded V4 source"); p.add_argument("--v5-script",default="",help="Optional override of embedded V5 source")
    p.add_argument("--variants",default="v4,v5"); p.add_argument("--models",default="llama4-scout-17b,llama3-groq-70b-tool-use")
    p.add_argument("--base-url",default="https://openai.rc.asu.edu/v1"); p.add_argument("--api-key",default="")
    p.add_argument("--v4-reference-split",default=""); p.add_argument("--v5-reference-split",default="")
    p.add_argument("--sample-size",type=int,default=0); p.add_argument("--random-seed",type=int,default=42)
    p.add_argument("--pattern-threshold-mode",choices=["median","fixed"],default="median")
    p.add_argument("--fixed-pattern-threshold",type=float,default=2.5); p.add_argument("--base-rate-prior-strength",type=float,default=30)
    p.add_argument("--device",choices=["auto","cpu","cuda"],default="auto")
    p.add_argument("--reward-oof-folds",type=int,default=5); p.add_argument("--reward-epochs",type=int,default=300)
    p.add_argument("--reward-lr",type=float,default=.03); p.add_argument("--reward-lambda-pattern",type=float,default=.05)
    p.add_argument("--reward-lambda-global",type=float,default=.002)
    p.add_argument("--reward-survey-weighted",action=argparse.BooleanOptionalAction,default=True)
    p.add_argument("--verbose-reward-training",action=argparse.BooleanOptionalAction,default=False)
    p.add_argument("--llm-reward-revision",action=argparse.BooleanOptionalAction,default=True)
    p.add_argument("--reward-guide-model",default=""); p.add_argument("--reward-revision-step",type=float,default=.12)
    p.add_argument("--reward-revision-min-gain",type=float,default=.0002)
    p.add_argument("--reward-revision-validation-fraction",type=float,default=.30)
    p.add_argument("--reward-revision-min-pattern-n",type=int,default=100); p.add_argument("--reward-revision-max-tokens",type=int,default=180)
    p.add_argument("--max-residual-adjustment",type=int,default=15); p.add_argument("--max-reflection-candidates",type=int,default=600)
    p.add_argument("--memory-api-sample-size",type=int,default=0,
                   help="Costly no-memory LLM calls used to build reflections; 0 uses the full memory split. Numerical reward fitting always uses full memory.")
    p.add_argument("--min-error-confidence",type=float,default=.2); p.add_argument("--min-reflection-confidence",type=float,default=.55)
    p.add_argument("--min-estimated-memory-value",type=float,default=.45); p.add_argument("--memory-dedup-jaccard",type=float,default=.7)
    p.add_argument("--memory-top-k",type=int,default=3); p.add_argument("--memory-min-similarity",type=float,default=.45)
    p.add_argument("--memory-same-pattern-only",action=argparse.BooleanOptionalAction,default=False)
    p.add_argument("--memory-direction-diversity",action=argparse.BooleanOptionalAction,default=True)
    p.add_argument("--memory-q-min-similarity",type=float,default=.5); p.add_argument("--memory-q-counterfactual-step",type=float,default=10)
    p.add_argument("--memory-q-max-neighbors",type=int,default=120); p.add_argument("--memory-q-shrink-kappa",type=float,default=20)
    p.add_argument("--memory-q-tau",type=float,default=.02); p.add_argument("--memory-min-empirical-q",type=float,default=-.002)
    p.add_argument("--include-sensitive-context",action=argparse.BooleanOptionalAction,default=False)
    p.add_argument("--decision-max-tokens",type=int,default=420); p.add_argument("--reflection-max-tokens",type=int,default=550)
    p.add_argument("--temperature",type=float,default=0); p.add_argument("--json-mode",choices=["auto","always","never"],default="auto")
    p.add_argument("--timeout",type=float,default=300); p.add_argument("--max-retries",type=int,default=4)
    p.add_argument("--max-concurrent-requests",type=int,default=12); p.add_argument("--concurrent-samples",type=int,default=12)
    p.add_argument("--progress-every",type=int,default=25); p.add_argument("--threshold-metric",choices=["balanced_accuracy","f1","accuracy"],default="balanced_accuracy")
    p.add_argument("--min-success-rate",type=float,default=.995)
    p.add_argument("--run-test-without-memory",action=argparse.BooleanOptionalAction,default=True)
    p.add_argument("--dry-run",action="store_true"); p.add_argument("--overwrite",action="store_true")
    return p

async def async_main(args):
    np.random.seed(args.random_seed); random.seed(args.random_seed); torch.manual_seed(args.random_seed)
    variants=[x.strip() for x in args.variants.split(",") if x.strip()]
    models=[x.strip() for x in args.models.split(",") if x.strip()]
    v4,v5=import_project_modules(args); raw_all=prepare_raw(args.input_csv,v4,v5,variants)
    root=Path(args.output_dir); root.mkdir(parents=True,exist_ok=True)
    prepared={}
    for variant in variants:
        raw,scores,second=build_variant_scores(raw_all,variant,v4,v5)
        ref=args.v4_reference_split if variant=="v4" else args.v5_reference_split
        ass=load_reference_split(ref,raw_all) if ref else fallback_split(scores,args.random_seed+(0 if variant=="v4" else 10))
        ass=ass[ass.source_row_index.isin(scores.index)]; ass=downsample_eval(ass,args.sample_size,args.random_seed+100)
        src=sorted(set(ass.source_row_index.astype(int))); raw=raw.loc[src]; scores=scores.loc[src]
        memsrc=ass.loc[ass.split=="memory","source_row_index"].astype(int).tolist()
        th=fit_thresholds(scores.loc[memsrc],args.pattern_threshold_mode,args.fixed_pattern_threshold)
        scores=assign_patterns(scores,th,variant,v4,v5); br=fit_base_rates(scores.loc[memsrc],args.base_rate_prior_strength)
        prepared[variant]=(raw,scores,ass,th,br)
        (root/variant).mkdir(exist_ok=True)
        scores.to_csv(root/variant/"selected_hbm_profiles.csv")
        ass.to_csv(root/variant/"split_assignments.csv",index=False)
        pd.DataFrame([{"pattern":p,**x} for p,x in br.items()]).to_csv(root/variant/"pattern_base_rates.csv",index=False)
        print(f"[{variant}] selected={len(scores):,} splits={ass.split.value_counts().to_dict()} second_construct={second}")
    device=choose_device(args.device); print("[reward device]",device)
    if args.dry_run:
        for variant,(raw,scores,ass,th,br) in prepared.items():
            memsrc=ass.loc[ass.split=="memory","source_row_index"].astype(int).tolist()
            art=fit_reward_model(scores.loc[memsrc],br,variant,args,device)
            pr=reward_predict(scores.head(3),variant,art)
            for i in pr.index[:2]:
                prof=build_profile(raw.loc[i],scores.loc[i],variant,v4,v5,args.include_sensitive_context)
                print(f"\n--- {variant} REWARD PRIOR ---\n",pr.loc[i].to_dict())
                print("--- DECISION PROMPT ---\n",decision_prompt(prof,pr.loc[i],[],args)[:5000])
        print("Dry run complete; no API calls.")
        return
    if AsyncOpenAI is None: raise RuntimeError("pip install -U openai httpx")
    key=args.api_key or os.getenv("ASU_OPENAI_API_KEY","") or os.getenv("OPENAI_API_KEY","")
    if not key: raise RuntimeError("Set ASU_OPENAI_API_KEY / OPENAI_API_KEY or pass --api-key")
    http=httpx.AsyncClient(timeout=args.timeout,trust_env=False)
    client=AsyncOpenAI(api_key=key,base_url=args.base_url,http_client=http,max_retries=0,timeout=args.timeout)
    sem=asyncio.Semaphore(max(1,args.max_concurrent_requests))
    jm={}
    for model in models:
        jm[model]=True if args.json_mode=="always" else False if args.json_mode=="never" else await probe_json_mode(client,model)
        print(f"[json_mode] {model} -> {jm[model]}")
    summaries=[]
    for variant,data in prepared.items():
        for model in models:
            try:
                summaries.append(await run_one(*data,variant,v4,v5,model,root,client,sem,jm[model],args,device))
            except Exception as exc:
                fail={"created_at":utc_now(),"variant":variant,"model":model,"error_type":type(exc).__name__,"error_message":str(exc)}
                print("EXPERIMENT FAILED",fail); append_jsonl(root/"benchmark_failures.jsonl",fail)
    rows=[]
    for s in summaries:
        for method,m in s["metrics"].items():
            rows.append({"variant":s["variant"],"model":s["model"],"method":method,
                         "memory_n":s["split_sizes"]["memory"],"calibration_n":s["split_sizes"]["calibration"],
                         "test_n":s["split_sizes"]["test"],"n_memories":s["n_final_memories"],
                         "accepted_reward_revisions":len(s["accepted_pattern_reward_guidance"]),**m})
    result_columns=["variant","model","method","memory_n","calibration_n","test_n","n_memories",
                    "accepted_reward_revisions","n","threshold","accuracy","balanced_accuracy","precision",
                    "recall","specificity","f1","roc_auc","average_precision","brier","log_loss"]
    pd.DataFrame(rows,columns=result_columns).to_csv(root/"benchmark_results.csv",index=False)
    (root/"all_summaries.json").write_text(json.dumps(summaries,ensure_ascii=False,indent=2,default=str),encoding="utf-8")
    await client.close(); await http.aclose()
    print(f"Completed summaries: {len(summaries)}")
    if rows: print(pd.DataFrame(rows).to_string(index=False))

def main():
    args=build_parser().parse_args()
    asyncio.run(async_main(args))

if __name__=="__main__": main()
